'use client'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Feedback, and `tsc --noEmit` passes on it,
// so the gate cannot catch it.
import './feedback.css'

/**
 * Feedback: the response to the player's last act.
 *
 * BDS-031 and REQ-045 both land here. The score increment floats up and fades
 * over `motion.floatUp`, and a wrong answer shakes over `motion.shake`; both
 * are `data-gs-animates="motion"` and stop dead under reduced motion. The
 * message itself is `data-gs-animates="emphasis"`, because a colour, glyph or
 * text change is how a player who cannot see movement still gets the answer.
 *
 * It performs nothing. It does not decide whether the last act was right, does
 * not know the running score, and does not settle a reward. The host has
 * already decided that by the time it hands this a variant, and this renders
 * it. Rendering is synchronous with the prop on purpose: REQ-045 puts a 100ms
 * ceiling on the gap between a tap and the first visible feedback, and nothing
 * here awaits anything between the prop landing and `[data-gs-feedback]`
 * landing in the DOM.
 */

export type FeedbackVariant = 'correct' | 'wrong' | 'score' | 'reward'

export interface FeedbackProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'children'> {
  /** Which of the four contract values this renders. */
  variant: FeedbackVariant
  /**
   * The text a player reads. Each variant has a default, so a host can render
   * a bare `<Feedback variant="correct" />` and still get an accessible
   * result; supplying a message (the reason an answer was wrong, a reward's
   * name) overrides the default entirely.
   */
  message?: string
  /**
   * The signed amount for a `score` variant's float-up, e.g. `50` or `-10`.
   * Rides `data-gs-delta`, which the attribute contract shares with any
   * element "reporting" a value's change rather than holding the value itself.
   */
  delta?: number
}

/** Fallbacks for a host that renders a variant with no message of its own. */
const DEFAULT_MESSAGE: Record<FeedbackVariant, string> = {
  correct: 'Correct',
  wrong: 'Wrong',
  score: 'Score',
  reward: 'Reward',
}

/** Glyphs, because colour alone is not an answer. Score has none: the number
 *  itself, floating up, is the signal. */
const GLYPH: Partial<Record<FeedbackVariant, string>> = {
  correct: '✓',
  wrong: '✕',
  reward: '★',
}

function formatDelta(delta: number): string {
  if (delta > 0) return `+${delta}`
  if (delta < 0) return `−${Math.abs(delta)}`
  return `${delta}`
}

export function Feedback({ variant, message, delta, className, ...rest }: FeedbackProps) {
  const label =
    message ?? (variant === 'score' && delta !== undefined ? formatDelta(delta) : DEFAULT_MESSAGE[variant])
  const glyph = GLYPH[variant]

  // BDS-031 names exactly two motion parts: the wrong-answer shake and the
  // score-pop float. Correct and reward hold still; their only change is the
  // message's own emphasis.
  const motionPart = variant === 'wrong' ? 'shake' : variant === 'score' ? 'float' : undefined

  const content = (
    <>
      {glyph ? (
        <span className="gs-feedback__glyph" data-gs-scope="feedback" data-gs-part="glyph" data-gs-animates="emphasis" aria-hidden="true">
          {glyph}
        </span>
      ) : null}
      <span className="gs-feedback__label gs-action-type" data-gs-scope="feedback" data-gs-part="label" data-gs-animates="emphasis" aria-hidden="true">
        {label}
      </span>
    </>
  )

  return (
    <div
      {...rest}
      className={['gs-feedback', className].filter(Boolean).join(' ')}
      data-gs-component="feedback"
      data-gs-feedback={variant}
      data-gs-delta={delta}
      role="status"
      aria-label={label}
    >
      {motionPart ? (
        <span
          className={`gs-feedback__${motionPart}`}
          data-gs-part={motionPart}
          data-gs-animates="motion"
          aria-hidden="true"
        >
          {content}
        </span>
      ) : (
        content
      )}
    </div>
  )
}

/* Feedback. Every value comes from a token; nothing here is a literal colour. */

.gs-feedback {
  display: inline-flex;
  align-items: center;
  gap: var(--gs-space-2);
}

.gs-feedback__label {
  /* A theme's type.action may set a case, and one that is read in four of the
     six places the action type is used is a theme half applied. */
  color: var(--gs-color-ink);
  /* Emphasis, not motion: the colour change survives reduced motion, because
     that is how a player who cannot see movement still gets the answer. */
  transition: color var(--gs-motion-emphasis) ease-out;
}

.gs-feedback__glyph {
  font-size: var(--gs-size-icon-control);
  line-height: 1;
  transition: opacity var(--gs-motion-emphasis) ease-out;
}

.gs-feedback[data-gs-feedback='correct'] .gs-feedback__label,
.gs-feedback[data-gs-feedback='correct'] .gs-feedback__glyph,
.gs-feedback[data-gs-feedback='score'] .gs-feedback__label {
  color: var(--gs-color-positive);
}

.gs-feedback[data-gs-feedback='wrong'] .gs-feedback__label,
.gs-feedback[data-gs-feedback='wrong'] .gs-feedback__glyph {
  color: var(--gs-color-negative);
}

.gs-feedback[data-gs-feedback='reward'] .gs-feedback__label,
.gs-feedback[data-gs-feedback='reward'] .gs-feedback__glyph {
  color: var(--gs-color-reward);
}

/* The shake and the float are the two motion parts BDS-031 names, and each is
   an `animation`, not a `transition`: the element mounts once, on
   settlement, with nothing earlier on screen to transition from. Under
   reduced motion, tokens.css forces animation-duration to 0s on anything
   carrying data-gs-animates="motion", so the keyframe still runs, just
   instantly, and its default fill-mode (none) leaves the label sitting at its
   ordinary, fully visible style rather than frozen on a faded-out frame. */
.gs-feedback__shake,
.gs-feedback__float {
  display: inline-flex;
  align-items: center;
  gap: var(--gs-space-2);
}

.gs-feedback__shake {
  animation: gs-feedback-shake var(--gs-motion-shake) ease-in-out;
}

.gs-feedback__float {
  animation: gs-feedback-float-up var(--gs-motion-float-up) ease-out;
}

@keyframes gs-feedback-shake {
  0%, 100% { transform: translateX(0); }
  20% { transform: translateX(-6px); }
  40% { transform: translateX(6px); }
  60% { transform: translateX(-6px); }
  80% { transform: translateX(6px); }
}

@keyframes gs-feedback-float-up {
  0% { transform: translateY(0); opacity: 1; }
  100% { transform: translateY(-24px); opacity: 0; }
}
